from pathlib import Path
import json
p=Path(__file__).parent;f=json.loads((p/'facts/inputs.json').read_text());s=(p/'report.md').read_text()
r=dict(ticker='HURN',as_of='2026-11-04',research_cutoff=f['cutoff'],price=f['price'],price_alternative=f['price_alternative'],price_timestamp=f['price_timestamp'],price_note='Yahoo and scanner173.015 versus StockAnalysis172.30; no single certified close.',scanner_date=f['scanner_date'],scanner_price=f['scanner_price'],research_status='Partial factual research; independent audit completed for partial factual scope',bear=None,base=None,bull=None,buy_ceiling=None,owner_fcf=None,equity_bridge=None,approved_entry=False,stage35_approved=False,latestCompleted=False,decision_es='En observación por conversión de caja, recompras financiadas y capital pendiente de normalización. Sin valoración ni entrada.',decision_en='Observation for cash conversion, funded buybacks and unresolved capital normalization. No valuation or entry.',publication_note='Keep RBR distinct from GAAP revenues; include software investment. Preserve discrepant prices and unknown next earnings date. No normalized owner FCF or integral equity bridge.')
for k,title in [('pros_es','Pros ES'),('cons_es','Contras ES'),('pros_en','Pros EN'),('cons_en','Cons EN')]:r[k]=[x[2:] for x in s.split('### '+title+'\n')[1].split('\n#')[0].strip().splitlines() if x.startswith('- ')]
(p/'publication.json').write_text(json.dumps(r,indent=2,ensure_ascii=False)+'\n')
